class Solution {
public:
    int maxArea(vector<int>& height) {
        int n = height.size();
        int maxA = 0;
        int l = 0, r = n - 1;
        while (l < r) {
            int h = min(height[l], height[r]);
            int area = h * (r - l);
            if (area > maxA) maxA = area;
            if (height[l] < height[r]) l++;
            else r--;
        }
        return maxA;
    }
};
